// DevCraft Admin: start
/**
 * Проверяет «пустое» значение для [has] / сравнения с "".
 * Пусто: null-подобное, "", только ASCII whitespace. Не пусто: &nbsp;, U+00A0.
 */
function dc_is_empty_template_value($value) {
	if ($value === null) {
		return true;
	}

	$value = (string) $value;

	if ($value === '') {
		return true;
	}

	return preg_replace('/[ \t\n\r\0\x0B]+/', '', $value) === '';
}

/**
 * Делит блок на then/else по первому top-level [else] (вложенные [if]/[has] игнорируются).
 *
 * @return array{0: string, 1: string}
 */
function dc_split_else_block($content) {
	$content = (string) $content;
	$pos     = 0;
	$depth   = 0;
	$len     = strlen($content);

	while ($pos < $len && preg_match('/\[else\]|\[if\b[^\]]*\]|\[\/if\]|\[has\b[^\]]*\]|\[\/has\]/i', $content, $m, PREG_OFFSET_CAPTURE, $pos)) {
		$tag = $m[0][0];
		$at  = (int) $m[0][1];

		if (strcasecmp($tag, '[else]') === 0 && $depth === 0) {
			return array(substr($content, 0, $at), substr($content, $at + strlen($tag)));
		}

		if (preg_match('/^\[(\/)?(if|has)\b/i', $tag, $tm)) {
			if (!empty($tm[1])) {
				$depth--;
				if ($depth < 0) {
					$depth = 0;
				}
			} else {
				$depth++;
			}
		}

		$pos = $at + strlen($tag);
	}

	return array($content, '');
}
// DevCraft Admin: end

// DevCraft Admin: start
