// DevCraft Admin: start
/**
 * Обрабатывает блоки [has value="…" condition="…" comparison="…"]…[else]…[/has].
 */
function has_check($text) {
	$process_has_block = function ($text) use (&$process_has_block) {
		$regex = '/\[has\b([^\]]*)\]/i';

		while (preg_match($regex, $text, $matches, PREG_OFFSET_CAPTURE)) {
			$full_open_tag = $matches[0][0];
			$attrs_raw     = $matches[1][0];
			$start_pos     = $matches[0][1];

			$value       = null;
			$condition   = '!=';
			$comparison  = '';
			$attrs_ok    = true;

			if (preg_match_all('/\b(value|condition|comparison)\s*=\s*(["\'])(.*?)\2/i', $attrs_raw, $am, PREG_SET_ORDER)) {
				foreach ($am as $attr) {
					$name = strtolower($attr[1]);
					$val  = $attr[3];
					if ($name === 'value') {
						$value = $val;
					} elseif ($name === 'condition') {
						$condition = $val !== '' ? $val : '!=';
					} elseif ($name === 'comparison') {
						$comparison = $val;
					}
				}
			}

			if ($value === null) {
				$attrs_ok = false;
			}

			$end_pos = $start_pos + strlen($full_open_tag);
			$depth   = 1;

			while ($depth > 0 && preg_match('/\[has\b[^\]]*\]|\[\/has\]/i', $text, $sub_matches, PREG_OFFSET_CAPTURE, $end_pos)) {
				if (stripos($sub_matches[0][0], '[/has]') !== false) {
					$depth--;
				} else {
					$depth++;
				}
				$end_pos = $sub_matches[0][1] + strlen($sub_matches[0][0]);
			}

			if ($depth > 0) {
				break;
			}

			if (!$attrs_ok) {
				break;
			}

			$block_content = substr($text, $start_pos + strlen($full_open_tag), $end_pos - $start_pos - strlen($full_open_tag) - strlen('[/has]'));
			$parts         = $this->dc_split_else_block($block_content);
			$then          = $parts[0];
			$else          = $parts[1];

			$left  = $this->dc_is_empty_template_value($value) ? '' : (string) $value;
			$right = $this->dc_is_empty_template_value($comparison) ? '' : (string) $comparison;
			$met   = $this->evaluate_operator($left, $condition, $right);

			$replacement = $met ? $process_has_block($then) : ($else !== '' ? $process_has_block($else) : '');
			$text        = substr_replace($text, $replacement, $start_pos, $end_pos - $start_pos);
		}

		return $text;
	};

	return $process_has_block($text);
}
// DevCraft Admin: end

